-- ---------- tables ----------
CREATE TABLE [stat] (
    [stat_id]                      INT NOT NULL,
    [code]                         NVARCHAR(100) NOT NULL,
    CONSTRAINT [PK_stat] PRIMARY KEY ([stat_id]),
    CONSTRAINT [UQ_stat_code] UNIQUE ([code])
);
CREATE TABLE [mod_op] (
    [mod_op_id]                    INT NOT NULL,
    [code]                         NVARCHAR(100) NOT NULL,
    CONSTRAINT [PK_mod_op] PRIMARY KEY ([mod_op_id]),
    CONSTRAINT [UQ_mod_op_code] UNIQUE ([code])
);
CREATE TABLE [tag] (
    [tag_id]                       INT IDENTITY(1,1) NOT NULL,
    [tag_family]                   NVARCHAR(100) NOT NULL,
    [code]                         NVARCHAR(100) NOT NULL,
    [enum_value]                   INT NOT NULL,
    CONSTRAINT [PK_tag] PRIMARY KEY ([tag_id]),
    CONSTRAINT [UQ_tag_tag_family_code] UNIQUE ([tag_family], [code]),
    CONSTRAINT [CK_tag_1] CHECK (tag_family IN ('item','enemy','gem','affix_group'))
);
CREATE TABLE [equipment_slot] (
    [slot_id]                      INT NOT NULL,
    [code]                         NVARCHAR(100) NOT NULL,
    [is_stim_slot]                 INT NOT NULL DEFAULT (0),
    CONSTRAINT [PK_equipment_slot] PRIMARY KEY ([slot_id]),
    CONSTRAINT [UQ_equipment_slot_code] UNIQUE ([code]),
    CONSTRAINT [CK_equipment_slot_1] CHECK (is_stim_slot IN (0,1))
);
CREATE TABLE [rarity] (
    [rarity_id]                    NVARCHAR(100) NOT NULL,
    [sort_order]                   INT NOT NULL,
    CONSTRAINT [PK_rarity] PRIMARY KEY ([rarity_id])
);
CREATE TABLE [rank] (
    [rank_id]                      NVARCHAR(100) NOT NULL,
    [display_name]                 NVARCHAR(100) NOT NULL,
    [ladder_order]                 INT NOT NULL,
    CONSTRAINT [PK_rank] PRIMARY KEY ([rank_id]),
    CONSTRAINT [UQ_rank_ladder_order] UNIQUE ([ladder_order])
);
CREATE TABLE [class_trait] (
    [class_trait_id]               NVARCHAR(100) NOT NULL,
    [display_name]                 NVARCHAR(100) NOT NULL,
    [description]                  NVARCHAR(MAX) NULL,
    [knob_cost_mult]               FLOAT NOT NULL DEFAULT (1.0),
    [knob_effect_mult]             FLOAT NOT NULL DEFAULT (1.0),
    [extra_points]                 FLOAT NOT NULL DEFAULT (0.0),
    [buff_cost_mult]               FLOAT NOT NULL DEFAULT (1.0),
    [nth_rule_cost_mult]           FLOAT NOT NULL DEFAULT (1.0),
    [nth_rule_effect_mult]         FLOAT NOT NULL DEFAULT (1.0),
    [nth_rule_effect_per_n]        FLOAT NOT NULL DEFAULT (0.0),
    [hit_rule_cost_mult]           FLOAT NOT NULL DEFAULT (1.0),
    [hit_rule_effect_mult]         FLOAT NOT NULL DEFAULT (1.0),
    [per_hit_any_knob]             INT NOT NULL DEFAULT (0),
    [armour_per_always_rule]       FLOAT NOT NULL DEFAULT (0.0),
    [armour_per_when_fire]         FLOAT NOT NULL DEFAULT (0.0),
    [when_buff_seconds]            FLOAT NOT NULL DEFAULT (4.0),
    [damage_per_10_armour]         FLOAT NOT NULL DEFAULT (0.0),
    [move_speed_per_rule]          FLOAT NOT NULL DEFAULT (0.0),
    [move_speed_per_knob_step]     FLOAT NOT NULL DEFAULT (0.0),
    [moving_damage_more]           FLOAT NOT NULL DEFAULT (0.0),
    [moving_damage_more_per_speed] FLOAT NOT NULL DEFAULT (0.0),
    [full_life_damage_more]        FLOAT NOT NULL DEFAULT (0.0),
    [phase_through_enemies]        INT NOT NULL DEFAULT (0),
    CONSTRAINT [PK_class_trait] PRIMARY KEY ([class_trait_id])
);
CREATE TABLE [character_class] (
    [class_id]                     NVARCHAR(100) NOT NULL,
    [display_name]                 NVARCHAR(100) NOT NULL,
    [tagline]                      NVARCHAR(100) NULL,
    [description]                  NVARCHAR(MAX) NULL,
    [sort_order]                   INT NOT NULL DEFAULT (0),
    [accent_color]                 NVARCHAR(100) NOT NULL DEFAULT ('#00E5FF'),
    [base_strength]                INT NOT NULL DEFAULT (8),
    [base_dexterity]               INT NOT NULL DEFAULT (8),
    [base_intelligence]            INT NOT NULL DEFAULT (8),
    [model_scene_path]             NVARCHAR(100) NULL,
    [model_scale]                  FLOAT NOT NULL DEFAULT (1.0),
    [starting_weapon_id]           NVARCHAR(100) NULL,
    [starting_skill_gem_id]        NVARCHAR(100) NULL,
    [class_trait_id]               NVARCHAR(100) NULL,
    CONSTRAINT [PK_character_class] PRIMARY KEY ([class_id])
);
CREATE TABLE [weapon_type] (
    [weapon_type_id]               NVARCHAR(100) NOT NULL,
    [display_name]                 NVARCHAR(100) NOT NULL,
    [base_range]                   FLOAT NOT NULL DEFAULT (0.3),
    [animation_set]                NVARCHAR(100) NULL,
    [two_handed]                   INT NOT NULL DEFAULT (0),
    [skill_mana_cost]              FLOAT NOT NULL DEFAULT (0.0),
    [attack_behavior]              NVARCHAR(100) NULL,
    CONSTRAINT [PK_weapon_type] PRIMARY KEY ([weapon_type_id])
);
CREATE TABLE [weapon_type_tag] (
    [weapon_type_id]               NVARCHAR(100) NOT NULL,
    [tag_id]                       INT NOT NULL,
    CONSTRAINT [PK_weapon_type_tag] PRIMARY KEY ([weapon_type_id], [tag_id])
);
CREATE TABLE [equipment_type] (
    [equipment_type_id]            NVARCHAR(100) NOT NULL,
    [display_name]                 NVARCHAR(100) NOT NULL,
    [slot_id]                      INT NOT NULL,
    CONSTRAINT [PK_equipment_type] PRIMARY KEY ([equipment_type_id])
);
CREATE TABLE [equipment_type_tag] (
    [equipment_type_id]            NVARCHAR(100) NOT NULL,
    [tag_id]                       INT NOT NULL,
    CONSTRAINT [PK_equipment_type_tag] PRIMARY KEY ([equipment_type_id], [tag_id])
);
CREATE TABLE [skill_gem] (
    [skill_gem_id]                 NVARCHAR(100) NOT NULL,
    [display_name]                 NVARCHAR(100) NOT NULL,
    [description]                  NVARCHAR(MAX) NULL,
    [behavior_script]              NVARCHAR(100) NULL,
    [max_support_slots]            INT NOT NULL DEFAULT (3),
    [base_mana_cost]               FLOAT NOT NULL DEFAULT (0.0),
    [base_flags_json]              NVARCHAR(MAX) NOT NULL DEFAULT ('{}'),
    [program_limits_json]          NVARCHAR(MAX) NULL,
    CONSTRAINT [PK_skill_gem] PRIMARY KEY ([skill_gem_id])
);
CREATE TABLE [skill_gem_tag] (
    [skill_gem_id]                 NVARCHAR(100) NOT NULL,
    [tag_id]                       INT NOT NULL,
    CONSTRAINT [PK_skill_gem_tag] PRIMARY KEY ([skill_gem_id], [tag_id])
);
CREATE TABLE [skill_gem_modifier] (
    [skill_gem_id]                 NVARCHAR(100) NOT NULL,
    [seq]                          INT NOT NULL,
    [stat_id]                      INT NOT NULL,
    [mod_op_id]                    INT NOT NULL,
    [value]                        FLOAT NOT NULL,
    CONSTRAINT [PK_skill_gem_modifier] PRIMARY KEY ([skill_gem_id], [seq])
);
CREATE TABLE [skill_gem_required_weapon] (
    [skill_gem_id]                 NVARCHAR(100) NOT NULL,
    [weapon_type_id]               NVARCHAR(100) NOT NULL,
    CONSTRAINT [PK_skill_gem_required_weapon] PRIMARY KEY ([skill_gem_id], [weapon_type_id])
);
CREATE TABLE [support_gem] (
    [support_gem_id]               NVARCHAR(100) NOT NULL,
    [display_name]                 NVARCHAR(100) NOT NULL,
    [description]                  NVARCHAR(MAX) NULL,
    [behavior_script]              NVARCHAR(100) NULL,
    [animation_override]           NVARCHAR(100) NULL,
    [mana_cost_increase]           FLOAT NOT NULL DEFAULT (0.25),
    [flag_modifiers_json]          NVARCHAR(MAX) NOT NULL DEFAULT ('{}'),
    [program_knobs_json]           NVARCHAR(MAX) NOT NULL DEFAULT ('[]'),
    CONSTRAINT [PK_support_gem] PRIMARY KEY ([support_gem_id])
);
CREATE TABLE [support_gem_allowed_tag] (
    [support_gem_id]               NVARCHAR(100) NOT NULL,
    [tag_id]                       INT NOT NULL,
    CONSTRAINT [PK_support_gem_allowed_tag] PRIMARY KEY ([support_gem_id], [tag_id])
);
CREATE TABLE [support_gem_modifier] (
    [support_gem_id]               NVARCHAR(100) NOT NULL,
    [seq]                          INT NOT NULL,
    [stat_id]                      INT NOT NULL,
    [mod_op_id]                    INT NOT NULL,
    [value]                        FLOAT NOT NULL,
    CONSTRAINT [PK_support_gem_modifier] PRIMARY KEY ([support_gem_id], [seq])
);
CREATE TABLE [stim] (
    [stim_id]                      NVARCHAR(100) NOT NULL,
    [kind]                         NVARCHAR(100) NOT NULL,
    [base_amount]                  FLOAT NOT NULL DEFAULT (60.0),
    [amount_per_level]             FLOAT NOT NULL DEFAULT (0.08),
    [amount_roll_min]              FLOAT NOT NULL DEFAULT (0.85),
    [amount_roll_max]              FLOAT NOT NULL DEFAULT (1.15),
    [duration]                     FLOAT NOT NULL DEFAULT (2.5),
    [max_charges]                  INT NOT NULL DEFAULT (30),
    [charges_per_use]              INT NOT NULL DEFAULT (10),
    CONSTRAINT [PK_stim] PRIMARY KEY ([stim_id]),
    CONSTRAINT [CK_stim_1] CHECK (kind IN ('HEALTH','MANA'))
);
CREATE TABLE [item] (
    [item_id]                      NVARCHAR(100) NOT NULL,
    [display_name]                 NVARCHAR(100) NOT NULL,
    [item_kind]                    NVARCHAR(100) NOT NULL,
    [weapon_type_id]               NVARCHAR(100) NULL,
    [equipment_type_id]            NVARCHAR(100) NULL,
    [skill_gem_id]                 NVARCHAR(100) NULL,
    [support_gem_id]               NVARCHAR(100) NULL,
    [stim_id]                      NVARCHAR(100) NULL,
    [item_level]                   INT NOT NULL DEFAULT (1),
    [base_value]                   INT NOT NULL DEFAULT (10),
    [icon_path]                    NVARCHAR(100) NULL,
    [mesh_path]                    NVARCHAR(100) NULL,
    CONSTRAINT [PK_item] PRIMARY KEY ([item_id]),
    CONSTRAINT [CK_item_1] CHECK (item_kind IN ('weapon','equipment','skill_gem','support_gem','stim','quest')),
    CONSTRAINT [CK_item_2] CHECK ((item_kind = 'weapon' AND weapon_type_id IS NOT NULL) OR (item_kind = 'equipment' AND equipment_type_id IS NOT NULL) OR (item_kind = 'skill_gem' AND skill_gem_id IS NOT NULL) OR (item_kind = 'support_gem' AND support_gem_id IS NOT NULL) OR (item_kind = 'stim' AND stim_id IS NOT NULL) OR (item_kind = 'quest'))
);
CREATE TABLE [item_base_stat] (
    [item_id]                      NVARCHAR(100) NOT NULL,
    [stat_id]                      INT NOT NULL,
    [value]                        FLOAT NOT NULL,
    CONSTRAINT [PK_item_base_stat] PRIMARY KEY ([item_id], [stat_id])
);
CREATE TABLE [item_allowed_affix_tag] (
    [item_id]                      NVARCHAR(100) NOT NULL,
    [tag_id]                       INT NOT NULL,
    CONSTRAINT [PK_item_allowed_affix_tag] PRIMARY KEY ([item_id], [tag_id])
);
CREATE TABLE [affix] (
    [affix_id]                     NVARCHAR(100) NOT NULL,
    [display_name]                 NVARCHAR(100) NOT NULL,
    [affix_type]                   NVARCHAR(100) NOT NULL,
    [shape]                        NVARCHAR(100) NOT NULL,
    [weight]                       INT NOT NULL DEFAULT (100),
    [min_item_level]               INT NOT NULL DEFAULT (1),
    [level_half_life]              FLOAT NOT NULL DEFAULT (5.0),
    [stat_id]                      INT NULL,
    [mod_op_id]                    INT NULL,
    [min_value]                    FLOAT NULL,
    [max_value]                    FLOAT NULL,
    [min_stat_id]                  INT NULL,
    [max_stat_id]                  INT NULL,
    [added_min_low]                FLOAT NULL,
    [added_min_high]               FLOAT NULL,
    [added_max_low]                FLOAT NULL,
    [added_max_high]               FLOAT NULL,
    CONSTRAINT [PK_affix] PRIMARY KEY ([affix_id]),
    CONSTRAINT [CK_affix_1] CHECK (affix_type IN ('prefix','suffix')),
    CONSTRAINT [CK_affix_2] CHECK (shape IN ('SIMPLE','DAMAGE_RANGE','PERCENT_RANGE','PERCENT_MULT_RANGE'))
);
CREATE TABLE [affix_tag] (
    [affix_id]                     NVARCHAR(100) NOT NULL,
    [tag_id]                       INT NOT NULL,
    CONSTRAINT [PK_affix_tag] PRIMARY KEY ([affix_id], [tag_id])
);
CREATE TABLE [affix_exclusivity_group] (
    [affix_id]                     NVARCHAR(100) NOT NULL,
    [tag_id]                       INT NOT NULL,
    CONSTRAINT [PK_affix_exclusivity_group] PRIMARY KEY ([affix_id], [tag_id])
);
CREATE TABLE [enemy_modifier] (
    [enemy_modifier_id]            NVARCHAR(100) NOT NULL,
    [display_name_prefix]          NVARCHAR(100) NULL,
    [weight]                       INT NOT NULL DEFAULT (100),
    [min_rarity]                   NVARCHAR(100) NOT NULL DEFAULT ('magic'),
    [on_spawn_script]              NVARCHAR(100) NULL,
    [is_trait]                     INT NOT NULL DEFAULT (0),
    CONSTRAINT [PK_enemy_modifier] PRIMARY KEY ([enemy_modifier_id])
);
CREATE TABLE [enemy_modifier_tag] (
    [enemy_modifier_id]            NVARCHAR(100) NOT NULL,
    [tag_id]                       INT NOT NULL,
    CONSTRAINT [PK_enemy_modifier_tag] PRIMARY KEY ([enemy_modifier_id], [tag_id])
);
CREATE TABLE [enemy_modifier_stat] (
    [enemy_modifier_id]            NVARCHAR(100) NOT NULL,
    [seq]                          INT NOT NULL,
    [stat_id]                      INT NOT NULL,
    [mod_op_id]                    INT NOT NULL,
    [value]                        FLOAT NOT NULL,
    CONSTRAINT [PK_enemy_modifier_stat] PRIMARY KEY ([enemy_modifier_id], [seq])
);
CREATE TABLE [enemy] (
    [enemy_id]                     NVARCHAR(100) NOT NULL,
    [display_name]                 NVARCHAR(100) NOT NULL,
    [scene_path]                   NVARCHAR(100) NULL,
    [model_scene_path]             NVARCHAR(100) NULL,
    [capsule_radius]               FLOAT NOT NULL DEFAULT (0.4),
    [capsule_height]               FLOAT NOT NULL DEFAULT (1.8),
    [max_health]                   FLOAT NOT NULL DEFAULT (30.0),
    [armour]                       FLOAT NOT NULL DEFAULT (5.0),
    [move_speed]                   FLOAT NOT NULL DEFAULT (4.0),
    [aggro_range]                  FLOAT NOT NULL DEFAULT (15.0),
    [attack_range]                 FLOAT NOT NULL DEFAULT (2.0),
    [preferred_distance]           FLOAT NOT NULL DEFAULT (0.0),
    [flee_distance]                FLOAT NOT NULL DEFAULT (0.0),
    [kite_delay_min]               FLOAT NOT NULL DEFAULT (0.5),
    [kite_delay_max]               FLOAT NOT NULL DEFAULT (1.0),
    [min_attack_damage]            FLOAT NOT NULL DEFAULT (4.0),
    [max_attack_damage]            FLOAT NOT NULL DEFAULT (8.0),
    [attack_speed]                 FLOAT NOT NULL DEFAULT (0.5),
    [basic_attack_enabled]         INT NOT NULL DEFAULT (1),
    [skill_cooldown]               FLOAT NOT NULL DEFAULT (6.0),
    [cooldown_jitter]              FLOAT NOT NULL DEFAULT (2.0),
    [cast_lock_fraction]           FLOAT NOT NULL DEFAULT (1.0),
    [act_boss]                     INT NOT NULL DEFAULT (0),
    [skill_flag_overrides_json]    NVARCHAR(MAX) NOT NULL DEFAULT ('{}'),
    [skill_loops_json]             NVARCHAR(MAX) NOT NULL DEFAULT ('{}'),
    CONSTRAINT [PK_enemy] PRIMARY KEY ([enemy_id]),
    CONSTRAINT [CK_enemy_1] CHECK (flee_distance <= preferred_distance OR preferred_distance = 0)
);
CREATE TABLE [enemy_skill] (
    [enemy_id]                     NVARCHAR(100) NOT NULL,
    [seq]                          INT NOT NULL,
    [skill_gem_id]                 NVARCHAR(100) NOT NULL,
    CONSTRAINT [PK_enemy_skill] PRIMARY KEY ([enemy_id], [seq])
);
CREATE TABLE [enemy_skill_support] (
    [enemy_id]                     NVARCHAR(100) NOT NULL,
    [seq]                          INT NOT NULL,
    [support_gem_id]               NVARCHAR(100) NOT NULL,
    CONSTRAINT [PK_enemy_skill_support] PRIMARY KEY ([enemy_id], [seq], [support_gem_id])
);
CREATE TABLE [enemy_allowed_modifier_tag] (
    [enemy_id]                     NVARCHAR(100) NOT NULL,
    [tag_id]                       INT NOT NULL,
    CONSTRAINT [PK_enemy_allowed_modifier_tag] PRIMARY KEY ([enemy_id], [tag_id])
);
CREATE TABLE [enemy_innate_trait] (
    [enemy_id]                     NVARCHAR(100) NOT NULL,
    [trait_script]                 NVARCHAR(100) NOT NULL,
    CONSTRAINT [PK_enemy_innate_trait] PRIMARY KEY ([enemy_id], [trait_script])
);
CREATE TABLE [enemy_pool_rarity] (
    [enemy_id]                     NVARCHAR(100) NOT NULL,
    [rarity_id]                    NVARCHAR(100) NOT NULL,
    CONSTRAINT [PK_enemy_pool_rarity] PRIMARY KEY ([enemy_id], [rarity_id])
);
CREATE TABLE [act] (
    [act_number]                   INT NOT NULL,
    [title]                        NVARCHAR(100) NOT NULL,
    [subtitle]                     NVARCHAR(100) NULL,
    [convoy_route]                 INT NOT NULL DEFAULT (0),
    CONSTRAINT [PK_act] PRIMARY KEY ([act_number])
);
CREATE TABLE [waypoint] (
    [waypoint_id]                  NVARCHAR(100) NOT NULL,
    [act_number]                   INT NOT NULL,
    [seq]                          INT NOT NULL,
    [display_name]                 NVARCHAR(100) NOT NULL,
    [kind]                         NVARCHAR(100) NOT NULL,
    [scene_path]                   NVARCHAR(100) NOT NULL,
    [spawn_id]                     NVARCHAR(100) NOT NULL DEFAULT ('default'),
    [dungeon_level]                INT NOT NULL DEFAULT (0),
    [map_x]                        FLOAT NOT NULL DEFAULT (0.5),
    [map_y]                        FLOAT NOT NULL DEFAULT (0.5),
    [note]                         NVARCHAR(MAX) NULL,
    [on_foot]                      INT NOT NULL DEFAULT (0),
    [random_threats_min]           INT NOT NULL DEFAULT (0),
    [random_threats_max]           INT NOT NULL DEFAULT (0),
    [route_after_id]               NVARCHAR(100) NULL,
    [route_needs_key]              NVARCHAR(100) NULL,
    [route_needs_text]             NVARCHAR(MAX) NULL,
    CONSTRAINT [PK_waypoint] PRIMARY KEY ([waypoint_id]),
    CONSTRAINT [UQ_waypoint_act_number_seq] UNIQUE ([act_number], [seq]),
    CONSTRAINT [CK_waypoint_1] CHECK (kind IN ('TOWN','DUNGEON','BOSS'))
);
CREATE TABLE [waypoint_link] (
    [from_waypoint_id]             NVARCHAR(100) NOT NULL,
    [to_waypoint_id]               NVARCHAR(100) NOT NULL,
    CONSTRAINT [PK_waypoint_link] PRIMARY KEY ([from_waypoint_id], [to_waypoint_id])
);
CREATE TABLE [waypoint_threat] (
    [waypoint_id]                  NVARCHAR(100) NOT NULL,
    [threat_id]                    NVARCHAR(100) NOT NULL,
    CONSTRAINT [PK_waypoint_threat] PRIMARY KEY ([waypoint_id], [threat_id])
);
CREATE TABLE [waypoint_required_quest] (
    [waypoint_id]                  NVARCHAR(100) NOT NULL,
    [quest_id]                     NVARCHAR(100) NOT NULL,
    CONSTRAINT [PK_waypoint_required_quest] PRIMARY KEY ([waypoint_id], [quest_id])
);
CREATE TABLE [quest] (
    [quest_id]                     NVARCHAR(100) NOT NULL,
    [title]                        NVARCHAR(100) NOT NULL,
    [description]                  NVARCHAR(MAX) NULL,
    [ordered]                      INT NOT NULL DEFAULT (0),
    [reward_credits]               INT NOT NULL DEFAULT (0),
    [reward_support_choice]        INT NOT NULL DEFAULT (0),
    [next_quest_id]                NVARCHAR(100) NULL,
    [grants_rank_id]               NVARCHAR(100) NULL,
    CONSTRAINT [PK_quest] PRIMARY KEY ([quest_id])
);
CREATE TABLE [quest_prerequisite] (
    [quest_id]                     NVARCHAR(100) NOT NULL,
    [requires_quest_id]            NVARCHAR(100) NOT NULL,
    CONSTRAINT [PK_quest_prerequisite] PRIMARY KEY ([quest_id], [requires_quest_id]),
    CONSTRAINT [CK_quest_prerequisite_1] CHECK (quest_id <> requires_quest_id)
);
CREATE TABLE [quest_reward_item] (
    [quest_id]                     NVARCHAR(100) NOT NULL,
    [seq]                          INT NOT NULL,
    [item_id]                      NVARCHAR(100) NOT NULL,
    CONSTRAINT [PK_quest_reward_item] PRIMARY KEY ([quest_id], [seq])
);
CREATE TABLE [quest_objective] (
    [quest_id]                     NVARCHAR(100) NOT NULL,
    [seq]                          INT NOT NULL,
    [description]                  NVARCHAR(MAX) NOT NULL,
    [kind]                         NVARCHAR(100) NOT NULL,
    [target]                       NVARCHAR(100) NOT NULL DEFAULT (''),
    [required]                     INT NOT NULL DEFAULT (1),
    [hidden]                       INT NOT NULL DEFAULT (0),
    CONSTRAINT [PK_quest_objective] PRIMARY KEY ([quest_id], [seq]),
    CONSTRAINT [CK_quest_objective_1] CHECK (required > 0)
);
CREATE TABLE [exam] (
    [exam_id]                      NVARCHAR(100) NOT NULL,
    [rank_id]                      NVARCHAR(100) NOT NULL,
    [title]                        NVARCHAR(100) NOT NULL,
    [brief_json]                   NVARCHAR(MAX) NOT NULL DEFAULT ('[]'),
    [required_condition]           NVARCHAR(100) NULL,
    [required_condition_label]     NVARCHAR(100) NULL,
    [required_fires]               INT NOT NULL DEFAULT (3),
    [required_stop_loop]           INT NOT NULL DEFAULT (0),
    [required_variable]            INT NOT NULL DEFAULT (0),
    [required_routine]             INT NOT NULL DEFAULT (0),
    [required_callers]             INT NOT NULL DEFAULT (3),
    [required_order]               INT NOT NULL DEFAULT (0),
    [time_limit]                   FLOAT NOT NULL DEFAULT (75.0),
    [par_time]                     FLOAT NOT NULL DEFAULT (45.0),
    [par_damage]                   FLOAT NOT NULL DEFAULT (0.30),
    [fail_health]                  FLOAT NOT NULL DEFAULT (0.25),
    [enemy_level]                  INT NOT NULL DEFAULT (1),
    [spawn_radius]                 FLOAT NOT NULL DEFAULT (8.5),
    CONSTRAINT [PK_exam] PRIMARY KEY ([exam_id]),
    CONSTRAINT [UQ_exam_rank_id] UNIQUE ([rank_id])
);
CREATE TABLE [exam_wave] (
    [exam_id]                      NVARCHAR(100) NOT NULL,
    [wave_no]                      INT NOT NULL,
    [size]                         INT NOT NULL,
    [enemy_id]                     NVARCHAR(100) NOT NULL,
    [name]                         NVARCHAR(100) NULL,
    [note]                         NVARCHAR(MAX) NULL,
    [tint]                         NVARCHAR(100) NULL,
    CONSTRAINT [PK_exam_wave] PRIMARY KEY ([exam_id], [wave_no])
);
CREATE TABLE [exam_wave_modifier] (
    [exam_id]                      NVARCHAR(100) NOT NULL,
    [enemy_modifier_id]            NVARCHAR(100) NOT NULL,
    CONSTRAINT [PK_exam_wave_modifier] PRIMARY KEY ([exam_id], [enemy_modifier_id])
);
CREATE TABLE [exam_lent_item] (
    [exam_id]                      NVARCHAR(100) NOT NULL,
    [item_id]                      NVARCHAR(100) NOT NULL,
    CONSTRAINT [PK_exam_lent_item] PRIMARY KEY ([exam_id], [item_id])
);
CREATE TABLE [shop] (
    [shop_id]                      NVARCHAR(100) NOT NULL,
    [display_name]                 NVARCHAR(100) NOT NULL DEFAULT ('VENDOR'),
    [greeting]                     NVARCHAR(MAX) NULL,
    [random_slots]                 INT NOT NULL DEFAULT (6),
    [magic_chance]                 FLOAT NOT NULL DEFAULT (0.30),
    [rare_chance]                  FLOAT NOT NULL DEFAULT (0.10),
    [buy_markup]                   FLOAT NOT NULL DEFAULT (1.5),
    [sell_ratio]                   FLOAT NOT NULL DEFAULT (0.4),
    [infinite_fixed]               INT NOT NULL DEFAULT (1),
    [use_catalog]                  INT NOT NULL DEFAULT (1),
    [include_gems]                 INT NOT NULL DEFAULT (0),
    [level_window]                 INT NOT NULL DEFAULT (20),
    [level_bias]                   FLOAT NOT NULL DEFAULT (0.5),
    [allow_reroll]                 INT NOT NULL DEFAULT (1),
    [reroll_base_cost]             INT NOT NULL DEFAULT (40),
    [reroll_cost_per_level]        INT NOT NULL DEFAULT (10),
    [reroll_cost_growth]           FLOAT NOT NULL DEFAULT (1.5),
    CONSTRAINT [PK_shop] PRIMARY KEY ([shop_id]),
    CONSTRAINT [CK_shop_1] CHECK (magic_chance BETWEEN 0 AND 1),
    CONSTRAINT [CK_shop_2] CHECK (rare_chance BETWEEN 0 AND 1)
);
CREATE TABLE [shop_item] (
    [shop_id]                      NVARCHAR(100) NOT NULL,
    [item_id]                      NVARCHAR(100) NOT NULL,
    [list]                         NVARCHAR(100) NOT NULL,
    CONSTRAINT [PK_shop_item] PRIMARY KEY ([shop_id], [item_id], [list]),
    CONSTRAINT [CK_shop_item_1] CHECK (list IN ('fixed','random_pool','excluded'))
);
CREATE TABLE [shop_catalog_folder] (
    [shop_id]                      NVARCHAR(100) NOT NULL,
    [folder]                       NVARCHAR(100) NOT NULL,
    CONSTRAINT [PK_shop_catalog_folder] PRIMARY KEY ([shop_id], [folder])
);
CREATE TABLE [dialogue] (
    [dialogue_id]                  NVARCHAR(100) NOT NULL,
    [source]                       NVARCHAR(MAX) NOT NULL,
    CONSTRAINT [PK_dialogue] PRIMARY KEY ([dialogue_id])
);
CREATE TABLE [player_character] (
    [character_id]                 INT IDENTITY(1,1) NOT NULL,
    [slot_no]                      INT NOT NULL,
    [save_version]                 INT NOT NULL DEFAULT (1),
    [name]                         NVARCHAR(100) NOT NULL,
    [class_id]                     NVARCHAR(100) NOT NULL,
    [level]                        INT NOT NULL DEFAULT (1),
    [xp]                           INT NOT NULL DEFAULT (0),
    [strength]                     INT NOT NULL,
    [dexterity]                    INT NOT NULL,
    [intelligence]                 INT NOT NULL,
    [credits]                      INT NOT NULL DEFAULT (0),
    [last_town_id]                 NVARCHAR(100) NULL,
    [active_script_set]            INT NOT NULL DEFAULT (0),
    [playtime_seconds]             INT NOT NULL DEFAULT (0),
    [created_at]                   INT NOT NULL,
    [updated_at]                   INT NOT NULL,
    CONSTRAINT [PK_player_character] PRIMARY KEY ([character_id]),
    CONSTRAINT [UQ_player_character_slot_no] UNIQUE ([slot_no]),
    CONSTRAINT [CK_player_character_1] CHECK (slot_no BETWEEN 0 AND 9),
    CONSTRAINT [CK_player_character_2] CHECK (LEN(LTRIM(RTRIM(name))) > 0),
    CONSTRAINT [CK_player_character_3] CHECK (level >= 1),
    CONSTRAINT [CK_player_character_4] CHECK (xp >= 0),
    CONSTRAINT [CK_player_character_5] CHECK (credits >= 0)
);
CREATE TABLE [item_instance] (
    [instance_id]                  INT IDENTITY(1,1) NOT NULL,
    [character_id]                 INT NOT NULL,
    [item_id]                      NVARCHAR(100) NOT NULL,
    [rarity_id]                    NVARCHAR(100) NOT NULL DEFAULT ('normal'),
    [item_level]                   INT NOT NULL DEFAULT (1),
    [copied]                       INT NOT NULL DEFAULT (0),
    [stim_base_amount]             FLOAT NULL,
    [charges]                      INT NOT NULL DEFAULT (-1),
    CONSTRAINT [PK_item_instance] PRIMARY KEY ([instance_id])
);
CREATE TABLE [item_instance_affix] (
    [instance_id]                  INT NOT NULL,
    [seq]                          INT NOT NULL,
    [affix_id]                     NVARCHAR(100) NOT NULL,
    [rolled_value]                 FLOAT NULL,
    [rolled_min]                   FLOAT NULL,
    [rolled_max]                   FLOAT NULL,
    CONSTRAINT [PK_item_instance_affix] PRIMARY KEY ([instance_id], [seq])
);
CREATE TABLE [item_instance_stim_mod] (
    [instance_id]                  INT NOT NULL,
    [mod_id]                       NVARCHAR(100) NOT NULL,
    CONSTRAINT [PK_item_instance_stim_mod] PRIMARY KEY ([instance_id], [mod_id])
);
CREATE TABLE [inventory_entry] (
    [character_id]                 INT NOT NULL,
    [position]                     INT NOT NULL,
    [instance_id]                  INT NOT NULL,
    CONSTRAINT [PK_inventory_entry] PRIMARY KEY ([character_id], [position]),
    CONSTRAINT [UQ_inventory_entry_instance_id] UNIQUE ([instance_id])
);
CREATE TABLE [equipped_item] (
    [character_id]                 INT NOT NULL,
    [slot_id]                      INT NOT NULL,
    [instance_id]                  INT NOT NULL,
    CONSTRAINT [PK_equipped_item] PRIMARY KEY ([character_id], [slot_id]),
    CONSTRAINT [UQ_equipped_item_instance_id] UNIQUE ([instance_id])
);
CREATE TABLE [skill_socket] (
    [socket_id]                    INT IDENTITY(1,1) NOT NULL,
    [character_id]                 INT NOT NULL,
    [socket_index]                 INT NOT NULL,
    [gem_instance_id]              INT NULL,
    [action]                       NVARCHAR(100) NULL,
    CONSTRAINT [PK_skill_socket] PRIMARY KEY ([socket_id]),
    CONSTRAINT [UQ_skill_socket_character_id_socket_index] UNIQUE ([character_id], [socket_index])
);
CREATE TABLE [skill_socket_support] (
    [socket_id]                    INT NOT NULL,
