    CONSTRAINT [UQ_skill_socket_support_support_instance_id] UNIQUE ([support_instance_id])
);
CREATE TABLE [script_set_name] (
    [character_id]                 INT NOT NULL,
    [set_index]                    INT NOT NULL,
    [name]                         NVARCHAR(100) NOT NULL,
    CONSTRAINT [PK_script_set_name] PRIMARY KEY ([character_id], [set_index])
);
CREATE TABLE [skill_program] (
    [socket_id]                    INT NOT NULL,
    [set_index]                    INT NOT NULL,
    [program_json]                 NVARCHAR(MAX) NOT NULL,
    CONSTRAINT [PK_skill_program] PRIMARY KEY ([socket_id], [set_index])
);
CREATE TABLE [script_library_entry] (
    [character_id]                 INT NOT NULL,
    [skill_gem_id]                 NVARCHAR(100) NOT NULL,
    [name]                         NVARCHAR(100) NOT NULL,
    [program_json]                 NVARCHAR(MAX) NOT NULL,
    [saved_order]                  INT NOT NULL,
    CONSTRAINT [PK_script_library_entry] PRIMARY KEY ([character_id], [skill_gem_id], [name]),
    CONSTRAINT [CK_script_library_entry_1] CHECK (LEN(name) <= 14)
);
CREATE TABLE [script_routine] (
    [character_id]                 INT NOT NULL,
    [seq]                          INT NOT NULL,
    [name]                         NVARCHAR(100) NOT NULL,
    [body_json]                    NVARCHAR(MAX) NOT NULL,
    CONSTRAINT [PK_script_routine] PRIMARY KEY ([character_id], [seq]),
    CONSTRAINT [UQ_script_routine_character_id_name] UNIQUE ([character_id], [name])
);
CREATE TABLE [character_quest] (
    [character_id]                 INT NOT NULL,
    [quest_id]                     NVARCHAR(100) NOT NULL,
    [status]                       NVARCHAR(100) NOT NULL,
    CONSTRAINT [PK_character_quest] PRIMARY KEY ([character_id], [quest_id]),
    CONSTRAINT [CK_character_quest_1] CHECK (status IN ('ACTIVE','READY_TO_TURN_IN','COMPLETED'))
);
CREATE TABLE [character_objective_progress] (
    [character_id]                 INT NOT NULL,
    [quest_id]                     NVARCHAR(100) NOT NULL,
    [seq]                          INT NOT NULL,
    [count]                        INT NOT NULL DEFAULT (0),
    CONSTRAINT [PK_character_objective_progress] PRIMARY KEY ([character_id], [quest_id], [seq]),
    CONSTRAINT [CK_character_objective_progress_1] CHECK (count >= 0)
);
CREATE TABLE [pending_support_choice] (
    [character_id]                 INT NOT NULL,
