    CONSTRAINT [CK_exam_grade_1] CHECK (grade IN (0,1,2))
);
CREATE TABLE [deed] (
    [character_id]                 INT NOT NULL,
    [kind]                         NVARCHAR(100) NOT NULL,
    [target]                       NVARCHAR(100) NOT NULL,
    [count]                        INT NOT NULL DEFAULT (0),
    CONSTRAINT [PK_deed] PRIMARY KEY ([character_id], [kind], [target])
);

